// Limiares definidos pelo grupo (os mesmos do firmware do ESP32).
const LIMITES = { bpmMax: 120, bpmMin: 50, tempMax: 38.0, tempMin: 35.0 };

const p = msg.payload;
if (typeof p !== 'object' || p === null || typeof p.bpm !== 'number') {
    node.warn('mensagem ignorada: payload fora do formato esperado');
    return null;
}

const temp = typeof p.temp === 'number' ? p.temp : null;
const instante = p.ts > 0 ? p.ts * 1000 : Date.now();
const hora = new Date(instante).toLocaleTimeString('pt-BR');

// Os limiares sao reavaliados aqui, sem confiar nos flags do dispositivo:
// a regra clinica fica centralizada e pode mudar sem regravar o firmware.
const alertas = [];
if (p.bpm === 0) alertas.push('Sem pulso detectado');
else if (p.bpm > LIMITES.bpmMax) alertas.push('Taquicardia (' + p.bpm + ' bpm)');
else if (p.bpm < LIMITES.bpmMin) alertas.push('Bradicardia (' + p.bpm + ' bpm)');
if (temp === null) alertas.push('Falha no sensor de temperatura');
else if (temp > LIMITES.tempMax) alertas.push('Febre (' + temp.toFixed(1) + ' °C)');
else if (temp < LIMITES.tempMin) alertas.push('Hipotermia (' + temp.toFixed(1) + ' °C)');

const sync = context.get('sync') || { ativa: false, recuperadas: 0, comAlerta: 0, ultimoAlerta: '' };

if (p.atrasado) {
    // Amostra que ficou na fila offline do ESP32. Entra no resumo de
    // sincronizacao, mas nao mexe nos medidores nem no indicador de alerta,
    // que representam o estado ATUAL do paciente.
    if (!sync.ativa) Object.assign(sync, { ativa: true, recuperadas: 0, comAlerta: 0, ultimoAlerta: '' });
    sync.recuperadas++;
    if (alertas.length) {
        sync.comAlerta++;
        sync.ultimoAlerta = hora + ' - ' + alertas.join(' + ');
    }
    context.set('sync', sync);
    const texto = 'Sincronizando: ' + sync.recuperadas + ' recuperadas (' + sync.comAlerta +
        ' com alerta), ' + p.pendentes + ' ainda na fila';
    return [null, null, null, null, null, { payload: texto }, null];
}

let textoSync = null;
if (sync.ativa) {
    sync.ativa = false;
    context.set('sync', sync);
    textoSync = 'Ultima sincronizacao: ' + sync.recuperadas + ' amostras recuperadas, ' +
        sync.comAlerta + ' com alerta' + (sync.ultimoAlerta ? ' | ultimo: ' + sync.ultimoAlerta : '');
}

const emAlerta = alertas.length > 0;
const estadoAnterior = flow.get('estado') || 'NORMAL';
const estado = emAlerta ? 'ALERTA' : 'NORMAL';
flow.set('estado', estado);

const indicador = {
    payload: emAlerta ? alertas.join(' | ') : 'Sinais dentro dos limites',
    cor: emAlerta ? '#e53935' : '#43a047',
    estado: estado
};

// Notificacao so na transicao para alerta, para nao repetir a cada 2 s.
const notificacao = emAlerta && estadoAnterior !== 'ALERTA'
    ? { payload: indicador.payload, topic: 'CardioIA - paciente ' + p.paciente + ' - ' + hora }
    : null;

return [
    { topic: 'BPM', payload: p.bpm },
    temp === null ? null : { topic: 'Temperatura', payload: temp },
    temp === null ? null : { payload: temp },
    { payload: p.bpm },
    indicador,
    textoSync === null ? null : { payload: textoSync },
    notificacao
];

// "online" e publicado pelo ESP32 ao conectar; "offline" e o Last Will,
// publicado pelo broker quando a conexao cai sem despedida.
const online = msg.payload === 'online';
if (!online) flow.set('estado', 'OFFLINE');

const status = {
    payload: online ? 'ONLINE' : 'OFFLINE - sem dados em tempo real (ver fila offline ao reconectar)'
};
const indicador = online ? null : {
    payload: 'Dispositivo offline - ultima leitura pode estar desatualizada',
    cor: '#9e9e9e',
    estado: 'OFFLINE'
};
return [status, indicador];
